// Read McKay r38_27.g6.gz decompressed graph6 lines on stdin. A new red neighbor of degree seven certifies an old blue seven-set (its neighborhood). Exhaust remaining low-degree choices; a disjoint blue seven-set covers every subset of a tested leaf.
use std::io::{self,BufRead};
fn ind(mut c:u32,k:u32,a:&[u32;27])->bool{if k==0{return true}while c.count_ones()>=k{let i=c.trailing_zeros() as usize;c&=c-1;if ind(c&!a[i],k-1,a){return true}}false}
fn visit(s:u32,mut c:u32,a:&[u32;27],leaves:&mut u64){if s.count_ones()+c.count_ones()<5{return}if c==0{*leaves+=1;assert!(ind(((1<<27)-1)^s,7,a));return}while c!=0{let i=c.trailing_zeros() as usize;c&=c-1;visit(s|(1<<i),c&!a[i],a,leaves)}}
fn main(){let mut parents=0;let mut leaves=0;for line in io::stdin().lock().lines(){let l=line.unwrap();let b=l.as_bytes();assert_eq!(b[0],90);let mut a=[0u32;27];let mut k=0;for j in 0..27{for i in 0..j{if (b[1+k/6]-63)&(1<<(5-k%6))!=0{a[i]|=1<<j;a[j]|=1<<i}k+=1}}let mut low=0;for i in 0..27{assert!(a[i].count_ones()<=7);if a[i].count_ones()<7{low|=1<<i}}visit(0,low,&a,&mut leaves);parents+=1}assert_eq!(parents,477142);println!("parents={parents} low-degree terminal sets checked={leaves}")}
